'use strict';
const C=VerboCore,$=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={headers:[],people:[],history:[],device:'',deviceId:'',baseName:''},db,selected=null,pending=null,busy=false;
const field=(...names)=>state.headers.findIndex(h=>names.some(n=>C.norm(h)===C.norm(n)));
const nameOf=p=>p.values[field('Nome')]||'Sem nome';
const phoneIndex=()=>field('Telefone de Contato com DDD (WhatsApp)','Telefone','WhatsApp');
const emailIndex=()=>field('Email','E-mail');
function notice(msg,error=false){$('notice').textContent=msg;$('notice').className=error?'error':'';$('notice').hidden=false;}
function show(page){document.querySelectorAll('.page').forEach(s=>s.hidden=s.id!==page);document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));if(page==='base')renderBase();if(page==='history')renderHistory();window.scrollTo({top:0,behavior:'smooth'});}
function openDB(){return new Promise((resolve,reject)=>{const req=indexedDB.open('verbo-offline',1);req.onupgradeneeded=()=>req.result.createObjectStore('data');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
function readState(){return new Promise((resolve,reject)=>{const r=db.transaction('data').objectStore('data').get('state');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);});}
function persist(next){return new Promise((resolve,reject)=>{const tx=db.transaction('data','readwrite');tx.objectStore('data').put(next,'state');tx.oncomplete=()=>{state=next;resolve();};tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error||Error('Gravação interrompida.'));});}
async function action(fn){if(busy)return;busy=true;try{await fn();}catch(e){notice(e.message||'Não foi possível concluir. Seus dados anteriores foram mantidos.',true);}finally{busy=false;}}
function render(){
 $('total').textContent=state.people.length;$('decided').textContent=state.people.filter(p=>p.decisions.some(Boolean)).length;$('decision-count').textContent=state.people.reduce((s,p)=>s+p.decisions.filter(Boolean).length,0);
 $('empty-base').hidden=state.people.length>0;$('device').value=state.device;$('device-footer').textContent=state.device;$('recent').innerHTML=historyHTML([...state.history].sort((a,b)=>b.time.localeCompare(a.time)).slice(0,4));
 document.querySelectorAll('[data-export]').forEach(b=>b.disabled=!state.people.length);renderBase();renderHistory();
}
function historyHTML(items){return items.length?items.map(h=>`<div class="recent-item"><small>${esc(new Date(h.time).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}))}</small><strong>${esc(h.name)}</strong><p>${esc(h.decision)} · ${esc(h.device)}</p>${h.note?`<p>${esc(h.note)}</p>`:''}</div>`).join(''):'<div class="empty"><span class="empty-symbol">◷</span>Os registros vão aparecer aqui.<br>Uma decisão de cada vez.</div>';}
function renderHistory(){const q=C.norm($('history-search').value);const items=[...state.history].filter(h=>(!q||C.matchesName(h.name,q))).sort((a,b)=>b.time.localeCompare(a.time));$('history-list').innerHTML=historyHTML(items);}
function renderBase(){const q=C.norm($('base-search').value);const people=state.people.filter(p=>(!q||C.matchesName(nameOf(p),q)));$('base-list').innerHTML=people.length?`<div class="table-wrap"><table><thead><tr><th>Nome</th><th>Decisões</th><th></th></tr></thead><tbody>${people.map(p=>`<tr><td>${esc(nameOf(p))}</td><td>${p.decisions.filter(Boolean).length}</td><td><button data-person="${esc(p.id)}">Abrir →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Nenhuma pessoa encontrada.</div>';}
function search(){const q=$('search').value.trim();if(!q){$('results').innerHTML='';return;}const people=state.people.filter(p=>C.matchesName(nameOf(p),q));if(people.length===1){$('results').innerHTML='';openPerson(people[0].id);return;}$('results').innerHTML=people.length?people.map(p=>`<button class="search-result" data-person="${esc(p.id)}"><strong>${esc(nameOf(p))}</strong><br><small>${esc(p.values[phoneIndex()]||'Telefone não informado')} · ${esc(p.values[emailIndex()]||'E-mail não informado')}</small> →</button>`).join(''):'<p>Nenhuma pessoa encontrada. Tente outra parte do nome.</p>';$('person-card').hidden=true;}
function openPerson(ident){selected=state.people.find(p=>C.id(p.id)===C.id(ident));if(!selected)return;const p=selected,pi=phoneIndex(),ei=emailIndex();show('register');$('person-card').hidden=false;$('person-card').innerHTML=`<div class="person-top"><h2>${esc(nameOf(p))}</h2></div><form id="decision-form"><div class="contact-grid">${pi>=0?`<div><label for="person-phone">Telefone · confira com a pessoa</label><input id="person-phone" type="tel" value="${esc(p.values[pi])}"></div>`:''}${ei>=0?`<div><label for="person-email">E-mail · confira com a pessoa</label><input id="person-email" type="email" value="${esc(p.values[ei])}"></div>`:''}</div><div class="card-heading"><span class="step">02</span><div><h2>Qual é o próximo passo?</h2><p>Selecione uma decisão para este registro.</p></div></div>${C.DECISIONS.map((d,i)=>`<label class="choice"><input name="decision" type="radio" value="${i}" required>${esc(d)}${p.decisions[i]?'<span>Já registrada ✓</span>':''}</label>`).join('')}<label for="note">Observação (opcional)</label><textarea id="note" maxlength="500" placeholder="Algo importante para o acompanhamento…"></textarea><button class="primary save-decision" type="submit">Salvar decisão ✓</button></form>`;$('decision-form').onsubmit=e=>{e.preventDefault();action(saveDecision);};$('person-card').scrollIntoView({behavior:'smooth',block:'nearest'});}
async function saveDecision(){const input=document.querySelector('input[name="decision"]:checked');if(!input)return;const d=Number(input.value),next=structuredClone(state),p=next.people.find(p=>p.id===selected.id);const pi=phoneIndex(),ei=emailIndex();if(pi>=0)p.values[pi]=$('person-phone').value.trim();if(ei>=0)p.values[ei]=$('person-email').value.trim();p.decisions[d]=true;const entry={id:crypto.randomUUID(),personId:p.id,name:nameOf(p),decision:C.DECISIONS[d],note:$('note').value.trim(),time:new Date().toISOString(),device:state.device,deviceId:state.deviceId};next.history.push(entry);await persist(next);render();$('person-card').innerHTML=`<div class="success-panel"><span class="eyebrow">SALVO NESTE APARELHO</span><h2>Decisão registrada ✓</h2><p><strong>${esc(nameOf(p))}</strong><br>${esc(C.DECISIONS[d])}</p><button class="secondary" data-person="${esc(p.id)}">Registrar outra decisão</button><button class="text-button" id="next-person">Buscar outra pessoa →</button></div>`;$('next-person').onclick=()=>{$('person-card').hidden=true;$('search').value='';$('results').innerHTML='';$('search').focus();};}
async function readExcel(file){if(file.size>20*1024*1024)throw Error('O arquivo ultrapassa 20 MB.');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const sheet=book.Sheets['Base']||book.Sheets[book.SheetNames[0]];const parsed=C.parse(XLSX.utils.sheet_to_json(sheet,{header:1,defval:'',raw:true}));parsed.history=[];if(book.Sheets['Historico']){const records=XLSX.utils.sheet_to_json(book.Sheets['Historico'],{defval:''});for(const r of records){if(!r.Registro||!r.ID||!C.DECISIONS.includes(r.Decisao)||!Number.isFinite(Date.parse(r.Data_ISO)))continue;const p=parsed.people.find(p=>C.id(p.id)===C.id(r.ID));if(!p)continue;parsed.history.push({id:String(r.Registro),personId:p.id,name:String(r.Nome),decision:r.Decisao,note:String(r.Observacao||''),time:new Date(r.Data_ISO).toISOString(),device:String(r.Aparelho),deviceId:String(r.Dispositivo)});}}
return parsed;}
function addHistory(previous,incoming){const map=new Map(previous.map(h=>[h.id,h]));incoming.forEach(h=>{if(!map.has(h.id))map.set(h.id,h);});return [...map.values()];}
async function stageImport(file){if(!file)return;const parsed=await readExcel(file);if(state.history.length||state.people.some(p=>p.decisions.some(Boolean)))throw Error('Este aparelho já tem decisões. Use Consolidar celulares para preservar os registros. Para outro evento, use uma instalação separada.');pending={...parsed,baseName:file.name};$('import-summary').textContent=`${parsed.people.length} pessoas · ${parsed.headers.length} colunas originais. `+(parsed.generated?'Serão gerados IDs fixos a partir de 001.':'Os IDs da planilha serão preservados.');$('import-warning').textContent=parsed.generated?'Depois de importar, baixe a base com IDs e distribua esse arquivo a todos os celulares. Não gere outra numeração em outro aparelho.':'Confira se este é o mesmo arquivo distribuído à equipe.';$('import-dialog').showModal();}
async function confirmImport(){if(!pending)return;const next={...state,headers:pending.headers,people:pending.people,history:pending.history,baseName:pending.baseName};await persist(next);pending=null;$('import-dialog').close();selected=null;$('person-card').hidden=true;$('results').innerHTML='';render();notice('Base importada e salva neste aparelho. Baixe a base com IDs para distribuir à equipe.');}
function exportExcel(mode){if(!state.people.length)throw Error('Importe uma base primeiro.');const decisions=mode!=='base';const headers=['ID',...state.headers,...(decisions?C.DECISIONS:[])];const rows=state.people.map(p=>[p.id,...p.values,...(decisions?p.decisions.map(v=>v?'Sim':''):[])]);const book=XLSX.utils.book_new();const sheet=XLSX.utils.aoa_to_sheet([headers,...rows]);sheet['!cols']=headers.map((h,i)=>({wch:i===0?8:Math.min(45,Math.max(18,h.length+2))}));sheet['!autofilter']={ref:sheet['!ref']};XLSX.utils.book_append_sheet(book,sheet,'Base');if(decisions){const hist=[['Registro','ID','Nome','Decisao','Observacao','Data_ISO','Aparelho','Dispositivo'],...state.history.map(h=>[h.id,h.personId,h.name,h.decision,h.note,h.time,h.device,h.deviceId])];XLSX.utils.book_append_sheet(book,XLSX.utils.aoa_to_sheet(hist),'Historico');}const safe=state.device.replace(/[^a-zA-Z0-9_-]/g,'_');XLSX.writeFile(book,`Verbo_${decisions?'Decisoes_'+safe:'Base_com_IDs'}_${new Date().toISOString().slice(0,10)}.xlsx`,{compression:true});notice('Excel gerado. Confira o arquivo na pasta de downloads do aparelho.');}
async function consolidate(files){if(!state.people.length)throw Error('Importe primeiro a base numerada.');if(!files.length)return;let next=structuredClone(state),added=0,conflicts=0;for(const file of files){const incoming=await readExcel(file);if(incoming.generated)throw Error(file.name+': o arquivo não possui IDs. Use uma exportação do Verbo.');const result=C.merge(next,incoming);next={...next,headers:result.base.headers,people:result.base.people,history:addHistory(next.history,incoming.history)};added+=result.added;conflicts+=result.conflicts;}await persist(next);render();notice(`${files.length} arquivo(s) consolidado(s). ${added} nova(s) decisão(ões) marcada(s).${conflicts?' Há '+conflicts+' linha(s) com dados diferentes: os contatos e demais dados deste aparelho foram mantidos. Confira os arquivos de origem.':''} Agora exporte o Excel consolidado.`);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.page)show(b.dataset.page);if(b.dataset.go)show(b.dataset.go);if(b.dataset.person)openPerson(b.dataset.person);if(b.dataset.export)action(()=>exportExcel(b.dataset.export));});
$('search-form').onsubmit=e=>{e.preventDefault();search();};$('history-search').oninput=renderHistory;$('base-search').oninput=renderBase;
$('import-file').onchange=e=>{const file=e.target.files[0];e.target.value='';action(()=>stageImport(file));};$('merge-files').onchange=e=>{const files=[...e.target.files];e.target.value='';action(()=>consolidate(files));};$('cancel-import').onclick=()=>{pending=null;$('import-dialog').close();};$('confirm-import').onclick=()=>action(confirmImport);
$('save-device').onclick=()=>action(async()=>{const value=$('device').value.trim();if(!value)throw Error('Informe um nome para este aparelho.');await persist({...state,device:value});render();notice('Identificação salva. Os próximos registros usarão este nome.');});
function connection(){$('connection').textContent=navigator.onLine?'● Online':'● Sem conexão';}window.addEventListener('online',connection);window.addEventListener('offline',connection);connection();
let installPrompt;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e;$('install').hidden=false;});$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null;$('install').hidden=true;}};
async function offline(){if(!('serviceWorker' in navigator)||!window.isSecureContext){$('offline-status').textContent='Uso offline ainda não preparado';$('offline-detail').textContent='Abra por HTTPS ou localhost para preparar o aplicativo.';return;}try{await navigator.serviceWorker.register('./sw.js');await Promise.race([navigator.serviceWorker.ready,new Promise((_,reject)=>setTimeout(()=>reject(Error('Tempo de preparação excedido')),15000))]);const cache=await caches.open('verbo-shell-v2');const keys=await cache.keys();if(keys.length<8)throw Error('Cache incompleto');$('offline-status').textContent='Aplicativo preparado para uso offline';$('offline-detail').textContent='Importe a base neste aparelho e teste em modo avião antes do evento.';}catch(e){$('offline-status').textContent='Não foi possível confirmar o modo offline';$('offline-detail').textContent='Abra com internet novamente e aguarde. Não use no evento sem testar em modo avião.';}}
(async()=>{try{db=await openDB();const saved=await readState();if(saved)state=saved;else{state.deviceId=crypto.randomUUID();state.device='Celular '+state.deviceId.slice(0,4).toUpperCase();await persist(state);}render();const persistent=await navigator.storage?.persist?.();$('storage-status').textContent=persistent?'Armazenamento persistente autorizado. Exporte os registros como cópia de segurança.':'Dados salvos neste navegador. Exporte regularmente e não limpe os dados do app.';}catch(e){notice('Não foi possível abrir o armazenamento local. Não registre decisões neste navegador até resolver: '+e.message,true);document.querySelectorAll('button,input').forEach(x=>x.disabled=true);}await offline();})();
